/* Service worker of the Trento hike planner (generated by scripts/build_pwa.py, version 9b69c8561f).
 * App shell: answered from the cache at once and refreshed in the background (the new version is used on the next launch).
 * Leaflet from cdnjs: cache-first. Map tiles are NOT cached here (tile servers' usage policies); offline the map is grey but the
 * list, the verdicts and the place views still work because the whole timetable is inside index.html. */
const VERSION = '9b69c8561f';
const SHELL = 'shell-' + VERSION;
const LIB = 'lib-leaflet-1.9.4';
const SHELL_FILES = ['index.html', 'manifest.webmanifest', 'icons/icon-192.png', 'icons/icon-512.png', 'icons/maskable-512.png', 'icons/apple-touch-icon.png'];
const LIB_FILES = ['https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.css', 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.js', 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/layers.png', 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/layers-2x.png'];

self.addEventListener('install', (e) => {
  e.waitUntil((async () => {
    const shell = await caches.open(SHELL);
    await shell.addAll(SHELL_FILES.map((u) => new Request(u, { cache: 'reload' })));
    const lib = await caches.open(LIB);
    await Promise.allSettled(LIB_FILES.map(async (u) => { if (!(await lib.match(u))) await lib.add(u); }));   // best effort: the app still installs without the CDN
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('shell-') && k !== SHELL) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (e) => {
  const r = e.request;
  if (r.method !== 'GET') return;
  const u = new URL(r.url);
  if (u.origin === location.origin) {
    e.respondWith((async () => {
      const cache = await caches.open(SHELL);
      const key = r.mode === 'navigate' ? new Request('index.html') : r;
      const hit = await cache.match(key, { ignoreSearch: true });
      const fresh = fetch(r.mode === 'navigate' ? new Request('index.html', { cache: 'no-cache' }) : new Request(r, { cache: 'no-cache' }))
        .then((res) => { if (res && res.ok) cache.put(key, res.clone()); return res; }).catch(() => null);
      if (hit) { e.waitUntil(fresh); return hit; }
      return (await fresh) || Response.error();
    })());
  } else if (u.hostname === 'cdnjs.cloudflare.com') {
    e.respondWith((async () => {
      const lib = await caches.open(LIB);
      const hit = await lib.match(r);
      if (hit) return hit;
      try { const res = await fetch(r); if (res && res.ok) lib.put(r, res.clone()); return res; } catch (err) { return Response.error(); }
    })());
  }
});
